var t=`1315-chivito`;var n=`world-1315`;var o=`UY`;var a=`south-america`;var r=4;var s=40;var l={en:`Chivito`,ua:`Чівіто`};var g={en:`Chivito is a dish from Uruguay featuring beef sirloin, smoked ham, chicken egg, bread roll. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Чівіто, страва кухні країни Уругвай з такими основними складниками: яловичий сирлойн, копчена шинка, куряче яйце, булочка. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`beef-sirloin`,520,`g`],[`canola-oil`,45,`ml`],[`smoked-ham`,210,`g`]]},{en:`Boil the eggs for about 12 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 12 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:12,i:[[`chicken-egg`,4,`pcs`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:10,i:[[`bread-roll`,4,`pcs`],[`mozzarella`,220,`g`],[`tomato`,280,`g`],[`lettuce`,140,`g`],[`mayonnaise`,90,`g`]]},{en:`Grill the marinated portions from the preceding steps, turning to cook evenly and checking the safe internal temperature.`,ua:`Готуйте замариновані порції на грилі, перевертаючи для рівномірного нагрівання та перевіряючи безпечну температуру всередині.`,t:[`grilling`],m:6,i:[]}];var h={slug:t,id:n,country:`UY`,region:a,servings:4,minutes:40,title:l,text:g,steps:d};export{o as country,h as default,n as id,s as minutes,a as region,r as servings,t as slug,d as steps,g as text,l as title};